// ===== Communication explorer =====
// Every callsign, airport, waypoint and frequency below is a FICTIONAL educational example.
// Phraseology follows ICAO conventions in simplified form; real usage varies by country.
const PHRASE_CATS = { basics: "Basic words", instr: "Instructions", numbers: "Numbers & values", emerg: "Emergency & urgency", avoid: "Common mistakes" };
const PHRASES = [
  { w: "Roger", cat: "basics", means: "I have received all of your last transmission.", ex: "ATC: \"AeroLearn 451, traffic is a Cessna two miles ahead.\" — Pilot: \"Roger, AeroLearn 451.\"", tip: "Roger does NOT mean yes, and it is never enough when a readback is required." },
  { w: "Wilco", cat: "basics", means: "Will comply — I understand your message and will do what it says.", ex: "ATC: \"AeroLearn 451, report final.\" — Pilot: \"Wilco, AeroLearn 451.\"", tip: "Short for \"will comply\". Saying \"Roger, wilco\" is redundant — wilco already includes roger." },
  { w: "Affirm", cat: "basics", means: "Yes.", ex: "ATC: \"G-ZZXY, confirm you are VFR?\" — Pilot: \"Affirm, G-XY.\"", tip: "ICAO uses \"affirm\". In the USA you will often hear \"affirmative\"." },
  { w: "Negative", cat: "basics", means: "No / permission not granted / that is not correct / not capable.", ex: "Pilot: \"Request direct LUMEN.\" — ATC: \"Negative, maintain present heading.\"", tip: "" },
  { w: "Say again", cat: "basics", means: "Repeat all, or the following part, of your last transmission.", ex: "Pilot: \"Say again the squawk, AeroLearn 451.\"", tip: "Never say \"repeat\" — in military use it can mean \"fire again\"." },
  { w: "Standby", cat: "basics", means: "Wait and I will call you.", ex: "ATC: \"AeroLearn 451, standby.\"", tip: "Standby is NOT a clearance — you may not do anything new until called back." },
  { w: "Unable", cat: "basics", means: "I cannot comply with your request, instruction or clearance.", ex: "Pilot: \"Unable flight level 360 due weight, AeroLearn 451.\"", tip: "Usually followed by a reason. It is always better to say unable than to accept something you can't do." },
  { w: "Correction", cat: "basics", means: "I made an error in this transmission. The correct version is…", ex: "Pilot: \"Climbing flight level 240 — correction — flight level 140, AeroLearn 451.\"", tip: "" },
  { w: "Disregard", cat: "basics", means: "Ignore that last transmission.", ex: "ATC: \"AeroLearn 451, turn left heading 090 — disregard.\"", tip: "" },
  { w: "Confirm", cat: "basics", means: "I request verification of a clearance, instruction, action or information.", ex: "Pilot: \"Confirm cleared to land runway 09, AeroLearn 451?\"", tip: "If you are unsure, always confirm — never guess." },
  { w: "Acknowledge", cat: "basics", means: "Let me know that you have received and understood this message.", ex: "ATIS: \"…acknowledge information Bravo on first contact.\"", tip: "" },
  { w: "Read back", cat: "basics", means: "Repeat all, or the specified part, of this message back to me exactly as received.", ex: "ATC: \"AeroLearn 451, read back the clearance.\"", tip: "Safety items always need a readback: runways, clearances, hold short, altitudes, headings, speeds, frequencies, squawks." },
  { w: "How do you read", cat: "basics", means: "What is the readability of my transmission?", ex: "Pilot: \"Harbourton Tower, G-ZZXY, radio check 118.200, how do you read?\" — ATC: \"G-XY, readability 5.\"", tip: "Readability scale: 1 unreadable · 2 readable now and then · 3 readable with difficulty · 4 readable · 5 perfectly readable." },
  { w: "Break break", cat: "basics", means: "Separates messages to different aircraft on a very busy frequency.", ex: "ATC: \"…AeroLearn 451, cleared to land. Break break, G-XY, hold position.\"", tip: "A single \"break\" separates parts of a message to the same aircraft." },
  { w: "Over / Out", cat: "basics", means: "Over = my transmission is ended and I expect a reply. Out = this exchange is ended, no reply expected.", ex: "Mostly heard on HF or poor-quality links.", tip: "Rarely used on normal VHF. \"Over and out\" is a film cliché — the two words contradict each other." },
  { w: "Cleared", cat: "instr", means: "Authorised to proceed under the conditions specified.", ex: "ATC: \"AeroLearn 451, runway 24, cleared for take-off.\"", tip: "The word \"cleared\" is reserved for clearances. A pilot never takes off or lands without it at a controlled airport." },
  { w: "Line up and wait", cat: "instr", means: "Enter the runway and wait for a take-off clearance.", ex: "ATC: \"AeroLearn 451, runway 24, line up and wait.\"", tip: "You are on the runway but NOT cleared for take-off." },
  { w: "Hold short", cat: "instr", means: "Stop before reaching the specified point (usually a runway).", ex: "ATC: \"G-XY, hold short runway 24.\" — Pilot: \"Holding short runway 24, G-XY.\"", tip: "Always read back hold-short instructions — runway incursions are a major safety risk." },
  { w: "Go around", cat: "instr", means: "Abandon the approach and climb away.", ex: "ATC: \"AeroLearn 451, go around, I say again, go around, vehicle on the runway.\"", tip: "A go-around is a normal safety manoeuvre, not a failure." },
  { w: "Contact", cat: "instr", means: "Establish communication with another unit (call them).", ex: "ATC: \"AeroLearn 451, contact Westbrook Departure 124.350.\"", tip: "Contact = call them. Monitor = just listen." },
  { w: "Monitor", cat: "instr", means: "Listen out on a frequency without calling.", ex: "ATC: \"AeroLearn 451, monitor Westbrook Tower 118.700.\"", tip: "" },
  { w: "Maintain", cat: "instr", means: "Continue in accordance with the specified conditions.", ex: "ATC: \"AeroLearn 451, maintain altitude 3000 feet.\"", tip: "" },
  { w: "Report", cat: "instr", means: "Pass me the following information.", ex: "ATC: \"G-XY, report downwind.\"", tip: "" },
  { w: "Request", cat: "instr", means: "I would like to know / I wish to obtain.", ex: "Pilot: \"AeroLearn 451, request higher level.\"", tip: "" },
  { w: "Squawk", cat: "instr", means: "Set this code on the transponder.", ex: "ATC: \"AeroLearn 451, squawk 4521.\" — Pilot: \"Squawk 4521, AeroLearn 451.\"", tip: "\"Squawk ident\" means press the IDENT button so your blip flashes on the radar screen." },
  { w: "Altitude", cat: "numbers", means: "Height above mean sea level, using the local pressure setting (QNH).", ex: "\"Climb altitude two thousand five hundred feet.\"", tip: "Thousands and hundreds are spoken as words: \"two thousand five hundred\"." },
  { w: "Flight level", cat: "numbers", means: "Altitude on the standard pressure setting (1013 hPa), in hundreds of feet.", ex: "\"Climb flight level two four zero\" (24,000 ft on standard pressure).", tip: "Digits are spoken separately. Some countries say round levels as \"flight level one hundred\"." },
  { w: "Heading", cat: "numbers", means: "The direction to point the aircraft, in degrees magnetic.", ex: "\"Turn left heading one two zero.\"", tip: "Always three digits: zero niner zero, not \"ninety\"." },
  { w: "Frequency", cat: "numbers", means: "A radio channel in MHz, spoken digit by digit with \"decimal\".", ex: "\"Contact Tower one one eight decimal seven.\"", tip: "Trailing zeros are usually dropped: 118.700 is spoken \"one one eight decimal seven\"." },
  { w: "QNH", cat: "numbers", means: "The pressure setting for the altimeter so it shows altitude above sea level.", ex: "\"QNH one zero one six.\"", tip: "Always read back the QNH. In the USA the setting is given in inches: \"altimeter two niner niner two\"." },
  { w: "Tree · Fife · Niner", cat: "numbers", means: "Radio pronunciations of 3, 5 and 9 to make them clearer through static.", ex: "\"Squawk fife tree two niner.\"", tip: "\"Nine\" can sound like the German \"nein\" (no), so it becomes \"niner\"." },
  { w: "Mayday", cat: "emerg", means: "Distress: grave and imminent danger, immediate assistance required.", ex: "Fictional example: \"MAYDAY MAYDAY MAYDAY, Westbrook Tower, G-ZZXY, engine failure, forced landing, 2 miles north of the field, 1500 feet, 2 persons on board.\"", tip: "Said three times. Everyone else on the frequency stays quiet. Educational example only — never transmit a practice Mayday on a real frequency." },
  { w: "Pan-pan", cat: "emerg", means: "Urgency: a serious situation but no immediate danger.", ex: "Fictional example: \"PAN-PAN PAN-PAN PAN-PAN, Harbourton Approach, AeroLearn 451, passenger with a medical problem, request priority landing.\"", tip: "Also said three times. Pronounced \"pahn\"." },
  { w: "Stop transmitting", cat: "emerg", means: "ATC instruction for other stations to keep the frequency clear during an emergency.", ex: "ATC: \"All stations, stop transmitting — Mayday.\"", tip: "" },
  { w: "\"Affirmative\" / \"Yeah\"", cat: "avoid", means: "Use AFFIRM (ICAO) for yes. Casual words like \"yeah\" or \"yep\" can be lost in static.", ex: "✔ \"Affirm, AeroLearn 451.\"", tip: "\"Affirmative\" is standard in the USA, so you will hear both." },
  { w: "\"Roger\" for yes", cat: "avoid", means: "Roger only means \"received\". It does not answer a yes/no question or replace a readback.", ex: "✘ ATC: \"Confirm runway 24?\" — \"Roger.\"   ✔ \"Affirm, runway 24.\"", tip: "" },
  { w: "\"Take-off\" outside a clearance", cat: "avoid", means: "The words \"take-off\" are kept for the actual clearance (or cancelling it). Otherwise say \"departure\".", ex: "✔ \"Ready for departure.\"  ✘ \"Ready for take-off.\"", tip: "This rule came from accident investigations where \"take-off\" was misheard as a clearance." },
  { w: "\"Repeat\"", cat: "avoid", means: "Use SAY AGAIN to ask for a repeat, or I SAY AGAIN when repeating yourself.", ex: "✔ \"Say again your last, AeroLearn 451.\"", tip: "" },
  { w: "Missing callsign", cat: "avoid", means: "Every readback ends with your callsign so ATC knows who answered.", ex: "✘ \"Climb flight level 240.\"   ✔ \"Climb flight level 240, AeroLearn 451.\"", tip: "" },
];
